// Separate legacy integration. Do not mix with CookieConsentAssets/CookieConsentBanner.
if(!empty($modx->cookieConsentLegacyRendered))return '';
$modx->cookieConsentLegacyRendered=true;
$assets=$modx->runSnippet('CookieConsentAssets',$scriptProperties);if($assets!=='')$modx->regClientStartupHTMLBlock($assets);
$banner=$modx->runSnippet('CookieConsentBanner',$scriptProperties);if($banner!=='')$modx->regClientHTMLBlock($banner);
return '';

// Contract: [[!CookieConsentAssets]] exactly once in head. No banner or suppression flags.
try {
    require_once MODX_CORE_PATH.'components/cookieconsent/src/CookieConsentSettings.php';
    try {
        $data=CookieConsentSettings::read($modx);
        $registry=CookieConsentTexts::safeJson(CookieConsentServiceRegistry::publicRegistry($data['registry']));
    }catch(Throwable $e){$modx->log(\MODX\Revolution\modX::LOG_LEVEL_ERROR,'[CookieConsent] Invalid public configuration');$registry='{"schema":1,"services":[]}';}
    $configuration='<script type="application/json" id="cc-service-registry">'.$registry.'</script>';
    $assets=(string)$modx->getOption('assets_url');$css='css/cookie-consent.min.css';$js='js/cookie-consent/cookie-consent.min.js';
    if(!is_file(MODX_ASSETS_PATH.$css)||!is_file(MODX_ASSETS_PATH.$js))throw new RuntimeException('Frontend bundle missing');
    $url=static fn($path)=>htmlspecialchars($assets.$path.'?v='.substr(hash_file('sha256',MODX_ASSETS_PATH.$path),0,20),ENT_QUOTES,'UTF-8');
    return $configuration.'<link rel="stylesheet" href="'.$url($css).'"><script src="'.$url($js).'" defer></script>';
}catch(Throwable $e){$modx->log(\MODX\Revolution\modX::LOG_LEVEL_ERROR,'[CookieConsent] Frontend assets unavailable');return '';}

// Contract: [[!CookieConsentBanner]] exactly once before closing body. Only ready markup.
try {
    require_once MODX_CORE_PATH.'components/cookieconsent/src/CookieConsentBannerRenderer.php';
    $data=CookieConsentSettings::read($modx);$language=CookieConsentBannerRenderer::language($modx);
    $strings=CookieConsentTexts::resolve($data['texts'],$language,$data['registry']['services']);
    return CookieConsentBannerRenderer::render($modx->getChunk('CookiesPopup'),$strings,$data['options'],(string)$modx->getOption('assets_url'),$modx->getOption('mode',$scriptProperties,'live'),$data['registry']['services']);
}catch(Throwable $e){$modx->log(\MODX\Revolution\modX::LOG_LEVEL_ERROR,'[CookieConsent] Banner configuration unavailable');return '';}
